#include <stdio.h>
void area(int *a, int b){
    *a = *a + b;
}
int main(){
    int length = 9;
    int width = 4;
    area(&length, width);
    printf("%d", length);
    return 0;
}

#include <stdio.h>
void area(int *a, int b){
    *a = *a * b;
}
int main(){
    int length = 6;
    int width = 2;
    area(&length, width);
    printf("%d", length);
    return 0;
}

#include <stdio.h>
void area(int *a, int b){
    *a = *a * b;
}
int main(){
    int length = 9;
    int width = 4;
    area(&length, width);
    printf("%d", length);
    return 0;
}

#include <stdio.h>
void area(int a, int *b){
    *a = *a * b;
}
int main(){
    int length = 9;
    int width = 4;
    area(length, &width);
    printf("%d", length);
    return 0;
}

